D={
950053:("make light of / pay homage","**Make light of** = tratar como sem importância; **pay lip service** = elogiar sem agir; **pay homage** = homenagear.",[("Don't {{make light of}} it.","Não trate isso como pouca coisa."),("They only {{pay lip service}} to equality.","Eles só falam de igualdade da boca para fora."),("We {{pay homage}} to the founders.","Homenageamos os fundadores."),("He {{made light of}} the risk.","Ele minimizou o risco.")],"“Pay lip service” =",["elogiar sem agir","pagar com os lábios","beijar"],0,"Da boca para fora."),
84129:("Perguntas retóricas","Não pedem resposta: **If not now, who? How long must we wait for change?**",[("{{If not now, who}}?","Se não agora, quem?"),("{{How long must we wait}} for change?","Quanto tempo devemos esperar por mudança?"),("{{What kind of nation do we want}} to build?","Que tipo de nação queremos construir?"),("{{Who among us}} can stay silent?","Quem entre nós pode ficar calado?")],"Uma pergunta retórica…",["afirma algo sem pedir resposta","exige resposta","é sempre negativa"],0,"Afirma."),
950054:("gírias irlandesas","**Langer** = idiota; **sleeveen** = enrolão; **scundered** = envergonhado; **mot** = namorada; **slag off** = criticar; **act the maggot** = fazer bobagem.",[("They {{slag off}} the referee.","Eles criticam o árbitro."),("Stop {{acting the maggot}}.","Pare de fazer bobagem."),("A right {{langer}}.","Um idiota e tanto."),("I was {{scundered}}.","Fiquei morrendo de vergonha.")],"“Scundered” =",["envergonhado","assustado","cansado"],0,"Vergonha."),
84130:("Apelo emocional com ética","**Imagine a child waiting for news. We owe it to them to listen. Speak from the heart.**",[("{{Imagine a child}} waiting for news.","Imagine uma criança esperando notícias."),("{{We owe it to them}} to listen.","Devemos isso a eles: ouvir."),("{{Speak from the heart}} and be honest.","Fale com o coração e seja honesto."),("{{Think of the families}} affected.","Pense nas famílias afetadas.")],"“We owe it to them” =",["é nosso dever com eles","nós os devemos","eles nos devem"],0,"Dever moral."),
84131:("Construindo credibilidade","**As someone who has worked in schools for years… My record is clear. I would not say this lightly.**",[("{{As someone who has worked in schools for years}}, I urge caution.","Como alguém que trabalha em escolas há anos, peço cautela."),("{{My record is clear}}.","Meu histórico é claro."),("{{I would not say this lightly}}, but the evidence is strong.","Não digo isso levianamente, mas a evidência é forte."),("{{I speak from experience}}.","Falo por experiência.")],"Para ganhar credibilidade…",["cite sua experiência","fale mais alto","evite exemplos"],0,"Experiência."),
84132:("Apelos lógicos","**It follows that… If we accept this premise, we must… The argument is sound because…**",[("{{It follows that}} results should improve.","Segue-se que os resultados devem melhorar."),("{{If we accept this premise}}, we must change course.","Se aceitamos esta premissa, devemos mudar de rumo."),("{{The argument is sound because}} the evidence is strong.","O argumento é sólido porque a evidência é forte."),("{{Therefore}}, we act.","Portanto, agimos.")],"“Premise” =",["premissa","promessa","preço"],0,"Premissa."),
84133:("Antecipando objeções","**One might object that… I take that concern seriously, but… It would be easy to overlook…**",[("{{One might object that}} it takes too long.","Pode-se objetar que demora demais."),("{{I take that concern seriously, but}} the data differ.","Levo essa preocupação a sério, mas os dados divergem."),("{{It would be easy to overlook}} the human side.","Seria fácil ignorar o lado humano."),("{{Admittedly}}, it costs more.","É verdade que custa mais.")],"“One might object” =",["alguém poderia objetar","um objeto","eu objeto"],0,"Objeção."),
950055:("dance around","**Elephant in the room**; **dance around** = rodear o assunto; **clam up** = calar-se; **a tacit rule** = regra tácita.",[("Don't {{dance around}} the topic.","Não rode o assunto."),("He {{clammed up}}.","Ele se calou."),("It's {{a tacit rule}}.","É uma regra tácita."),("That's {{the elephant in the room}}.","Esse é o elefante na sala.")],"“Clam up” =",["calar-se","abrir-se","comer mariscos"],0,"Calar."),
84134:("Desmontando um argumento","**The premise is flawed because… The conclusion does not follow… The argument rests on a hidden premise.**",[("{{The premise is flawed}} because it assumes too much.","A premissa é falha porque supõe demais."),("{{The conclusion does not follow}} from the data.","A conclusão não decorre dos dados."),("{{The argument rests on}} one hidden premise.","O argumento se apoia numa premissa oculta."),("{{That claim is overstated}}.","Essa afirmação é exagerada.")],"“Rests on” =",["se apoia em","descansa em","para"],0,"Apoiar-se."),
950056:("back out of / sign off on","**Back out of** = desistir; **get round to** = arranjar tempo; **sign off on** = aprovar; **sit in on** = assistir como ouvinte.",[("He {{backed out of}} it.","Ele desistiu."),("I'll {{get round to}} it soon.","Arranjo tempo para isso logo."),("The boss {{signed off on}} it.","O chefe aprovou."),("May I {{sit in on}} the meeting?","Posso assistir à reunião?")],"“Sign off on” =",["aprovar","desligar","assinar embaixo só"],0,"Aprovar."),
84135:("Espantalhos e pistas falsas","**That is a straw man… a red herring… beside the point.**",[("{{That is a straw man}}, because it distorts my view.","Isso é um espantalho, porque distorce minha visão."),("{{That is a red herring}}, because it changes the topic.","Isso é uma pista falsa, porque muda de assunto."),("{{That is beside the point}}.","Isso está fora do ponto."),("{{Let's stay on topic}}.","Vamos manter o assunto.")],"“Beside the point” =",["fora do ponto","ao lado do ponto","no ponto"],0,"Irrelevante."),
84136:("Posição ética","**I take the view that… It is indefensible to… My conscience will not allow me to…**",[("{{I take the view that}} honesty comes first.","Sou da opinião de que a honestidade vem primeiro."),("{{It is indefensible to}} hide the truth.","É indefensável esconder a verdade."),("{{My conscience will not allow me to}} stay silent.","Minha consciência não me permite ficar calado."),("{{I cannot in good conscience}} agree.","Não posso, em sã consciência, concordar.")],"“Indefensible” =",["indefensável","indefinido","indeciso"],0,"Indefensável."),
84137:("Debatendo políticas","**The proposal would create… The burden of proof lies with… This policy would cause harm to…**",[("{{The proposal would create}} new jobs.","A proposta criaria novos empregos."),("{{The burden of proof lies with}} the supporters.","O ônus da prova cabe aos defensores."),("{{This policy would cause harm to}} young families.","Esta política prejudicaria famílias jovens."),("{{The costs outweigh the benefits}}.","Os custos superam os benefícios.")],"“The burden of proof” =",["o ônus da prova","o peso da prova","a prova pesada"],0,"Ônus."),
950057:("bail out / ride out","**Bail out** = socorrer financeiramente; **ride out** = atravessar uma crise; **get by** = ir levando; **scrape through**.",[("They {{bailed out}} the banks.","Socorreram os bancos."),("We'll {{ride out}} the storm.","Vamos atravessar a tempestade."),("We barely {{get by}}.","Mal vamos levando."),("He {{scraped through}} the exam.","Ele passou raspando.")],"“Ride out” =",["atravessar até passar","sair a cavalo","viajar"],0,"Aguentar."),
84138:("Defendendo uma ideia impopular","**I realize this may be unpopular, but… I am aware that I am in the minority… I stand by my reasoning.**",[("{{I realize this may be unpopular, but}} I believe it is right.","Sei que pode ser impopular, mas acredito que é certo."),("{{I am aware that I am in the minority}}, but the evidence is clear.","Sei que estou em minoria, mas a evidência é clara."),("{{I stand by}} my reasoning.","Mantenho meu raciocínio."),("{{With respect}}, I disagree.","Com respeito, discordo.")],"“Stand by” =",["manter/sustentar","ficar parado","apoiar o vizinho"],0,"Sustentar."),
84139:("Admitindo um ponto","**I stand corrected. On reflection, I must rethink… That is a fair criticism.**",[("{{I stand corrected}}, and I will revise my view.","Reconheço o erro e revisarei minha visão."),("{{On reflection}}, I must rethink my position.","Pensando bem, devo repensar minha posição."),("{{That is a fair criticism}}, and I will address it.","É uma crítica justa e vou tratá-la."),("{{You make a good point}}.","Você tem bom argumento.")],"“I stand corrected” =",["reconheço meu erro","fico em pé","corrija-me de pé"],0,"Admitir."),
950058:("off the record","**Off the record** = extraoficial; **on the back burner** = adiado; **a rule of thumb** = regra prática.",[("{{Off the record}}, no.","Extraoficialmente, não."),("It's {{on the back burner}}.","Está em banho-maria."),("As {{a rule of thumb}}, plan ahead.","Como regra prática, planeje com antecedência."),("Keep it {{under wraps}}.","Mantenha em sigilo.")],"“Back burner” =",["em segundo plano","queimador de trás","fogão"],0,"Adiado."),
84140:("Negociando sentidos","**Depending on how you read it… That is one possible interpretation… Both readings are defensible.**",[("{{Depending on how you read it}}, the answer differs.","Dependendo de como você lê, a resposta difere."),("{{That is one possible interpretation}}, but mine is slightly different.","É uma interpretação possível, mas a minha é um pouco diferente."),("{{Both readings are defensible}} if you give reasons.","Ambas as leituras são defensáveis se houver razões."),("{{It's open to interpretation}}.","Está aberto a interpretação.")],"“Defensible” =",["defensável","defensivo","defeituoso"],0,"Defensável."),
84141:("Histórias nos argumentos","**Let me tell you what happened to me. Picture a crowded bus… The moral of the story is clear.**",[("{{Let me tell you what happened to me}}.","Deixe-me contar o que aconteceu comigo."),("{{Picture}} a crowded bus on a rainy day.","Imagine um ônibus lotado num dia de chuva."),("{{The moral of the story is clear}}.","A moral da história é clara."),("{{This brings me to my point}}.","Isso me leva ao meu ponto.")],"“Picture” (verbo) =",["imaginar","fotografar","pintar"],0,"Imaginar."),
950059:("sons","**Thud / thump** (baque), **clang** (metal), **rustle** (folhas), **hiss** (sibilo), **screech** (guincho), **clatter**.",[("A dull {{thud}}.","Um baque surdo."),("Pans {{clatter}}.","Panelas ressoam."),("Leaves {{rustle}}.","Folhas farfalham."),("A fan {{whirs}} softly.","Um ventilador zumbe baixinho.")],"“Hiss” =",["sibilo","grito","estalo"],0,"Sibilo."),
84142:("Humor na persuasão","**A little humor lightens the mood. Timing is everything. Mind your manners.**",[("{{A little humor}} lightens the mood.","Um pouco de humor alivia o clima."),("{{Timing is everything}} in a speech.","O momento certo é tudo num discurso."),("{{Mind your manners}} in front of guests.","Cuide de suas maneiras diante dos convidados."),("{{Don't overdo it}}.","Não exagere.")],"“Timing” =",["momento certo","tempo de relógio","cronômetro"],0,"Timing."),
84143:("Lendo a plateia","**I can tell that you are not convinced. I am sensing some resistance. Let me adapt my tone.**",[("{{I can tell that}} you are not convinced.","Percebo que você não está convencido."),("{{I am sensing some resistance}} in the room.","Sinto alguma resistência na sala."),("{{Let me adapt my tone}}.","Deixe-me adaptar meu tom."),("{{Allow me to rephrase}}.","Permita-me reformular.")],"“Rephrase” =",["reformular","repetir","reescrever frase"],0,"Reformular."),
84144:("Encerramentos persuasivos","**In conclusion, the evidence is clear. I urge you to think it over. I leave you with one thought…**",[("{{In conclusion}}, the evidence is clear.","Em conclusão, a evidência é clara."),("{{I urge you to think it over}}.","Peço que reflitam."),("{{I leave you with one thought}}: what will you do?","Deixo uma reflexão: o que você fará?"),("{{Thank you for your attention}}.","Obrigado pela atenção.")],"“Leave you with a thought” =",["deixar uma reflexão","abandonar","esquecer"],0,"Reflexão."),
84145:("Persuasão em entrevistas","**I have a proven track record of… Let me give you a concrete example… I would bring value to…**",[("{{I have a proven track record}} of leading teams.","Tenho um histórico comprovado de liderar equipes."),("{{Let me give you a concrete example}}: I led a team of ten.","Deixe-me dar um exemplo concreto: liderei dez pessoas."),("{{I would bring value to}} your company.","Eu agregaria valor à sua empresa."),("{{I'm eager to contribute}}.","Estou ansioso para contribuir.")],"“Track record” =",["histórico de resultados","pista de corrida","gravação"],0,"Histórico."),
950060:("take with a pinch of salt","**Take with a pinch of salt** = duvidar um pouco; **wear thin** = perder o efeito; **jump through hoops** = passar por burocracia.",[("{{Take}} it {{with a pinch of salt}}.","Leve isso com um grão de sal."),("The excuse is {{wearing thin}}.","A desculpa está perdendo o efeito."),("I {{jumped through hoops}}.","Passei por mil exigências."),("It {{rings hollow}}.","Soa vazio.")],"“Wear thin” =",["perder o efeito","emagrecer","desgastar roupa só"],0,"Perder força."),
84146:("Moderando um painel","**Welcome to today's panel on… I will give the floor to… May I ask you to wrap up?**",[("{{Welcome to}} today's panel on the future of work.","Bem-vindos ao painel de hoje sobre o futuro do trabalho."),("{{I will give the floor to}} Professor Cruz.","Passo a palavra ao Professor Cruz."),("{{May I ask you to wrap up}}, in one sentence?","Posso pedir que conclua em uma frase?"),("{{Let's open the floor}} to questions.","Vamos abrir para perguntas.")],"“Give the floor to” =",["passar a palavra a","dar o chão a","derrubar"],0,"Palavra."),
950061:("strike a chord","**Strike a chord** = tocar fundo; **strike a nerve** = tocar num ponto sensível; **strike gold**; **strike a balance**.",[("It {{struck a chord}} with me.","Isso me tocou fundo."),("That {{struck a nerve}}.","Isso tocou num ponto sensível."),("They {{struck gold}}.","Eles deram sorte."),("We must {{strike a balance}}.","Precisamos encontrar equilíbrio.")],"“Strike a nerve” =",["tocar num ponto sensível","bater num nervo","dar choque"],0,"Ponto sensível."),
84147:("Perguntas hostis","**I do not accept the premise of your argument. With respect, that is not accurate. Let me address the substance.**",[("{{I do not accept the premise}} of your question.","Não aceito a premissa da sua pergunta."),("{{With respect, that is not accurate}}.","Com respeito, isso não é preciso."),("{{Let me address the substance}} of the issue.","Deixe-me tratar da essência da questão."),("{{I'd rather not speculate}}.","Prefiro não especular.")],"Diante de hostilidade…",["responda com calma","grite","ignore"],0,"Calma."),
84148:("Reconstruindo a confiança","**I take full responsibility. I will earn back your trust through my actions. Here is what I will do differently.**",[("{{I take full responsibility}} for the delay.","Assumo total responsabilidade pelo atraso."),("{{I will earn back your trust}} through my actions.","Reconquistarei sua confiança com ações."),("{{Here is what I will do differently}}: report weekly.","Eis o que farei diferente: reportar semanalmente."),("{{I deeply regret}} this.","Lamento profundamente isso.")],"“Earn back” =",["reconquistar","ganhar de volta dinheiro","voltar"],0,"Reconquistar."),
84149:("Falando com gravidade","**This is a defining moment. We stand at a crossroads. It is with a heavy heart that I…**",[("{{This is a defining moment}} for our country.","Este é um momento decisivo para nosso país."),("{{We stand at a crossroads}} once again.","Estamos mais uma vez numa encruzilhada."),("{{It is with a heavy heart that}} I stand before you.","É com o coração pesado que estou diante de vocês."),("{{History will judge us}}.","A história nos julgará.")],"“Heavy heart” =",["tristeza profunda","coração gordo","pesadelo"],0,"Tristeza."),
84150:("Sátira e paródia","**This sketch is a parody of… It lampoons the hypocrisy of… It is meant to be taken lightly.**",[("{{This sketch is a parody of}} a famous movie.","Este esquete é uma paródia de um filme famoso."),("{{It lampoons}} the hypocrisy of big companies.","Satiriza a hipocrisia das grandes empresas."),("{{It is meant to be taken lightly}}.","Deve ser levado de forma leve."),("{{The humor is biting}}.","O humor é mordaz.")],"“Lampoon” =",["satirizar","lâmpada","lançar"],0,"Satirizar."),
950062:("be that as it may","**Be that as it may / for all that** aceitam um ponto e seguem o argumento; **at any rate / in any case** encerram.",[("{{Be that as it may}}, it was wrong.","Seja como for, foi errado."),("{{For all that}}, he tried.","Apesar de tudo, ele tentou."),("{{At any rate}}, we won.","De qualquer modo, vencemos."),("{{In any case}}, we're done.","Em todo caso, terminamos.")],"“At any rate” =",["de qualquer modo","a qualquer taxa","por baixo preço"],0,"De qualquer modo."),
950063:("make a killing","**Make a killing** = lucrar muito; **spark controversy**; **fuel speculation** = alimentar boatos; **cast aspersions**.",[("They {{made a killing}}.","Eles lucraram horrores."),("The post {{sparked controversy}}.","A postagem gerou polêmica."),("It {{fuels speculation}}.","Isso alimenta especulações."),("He {{cast aspersions}} on her work.","Ele difamou o trabalho dela.")],"“Make a killing” =",["lucrar muito","matar","assassinar"],0,"Lucro enorme."),
84151:("Retórica na publicidade","**Because you deserve it, treat yourself. It is worth every penny. The ad makes a bold claim.**",[("{{Because you deserve it}}, treat yourself.","Porque você merece, presenteie-se."),("It is {{worth every penny}} if you check first.","Vale cada centavo se você conferir antes."),("The ad {{makes a bold claim}} about taste.","O anúncio faz uma afirmação ousada sobre o sabor."),("{{Don't fall for}} the hype.","Não caia no hype.")],"“Worth every penny” =",["vale cada centavo","custa um centavo","pouco dinheiro"],0,"Vale."),
84152:("Retórica na política","**Let me be perfectly clear: we will not give up. We will leave no stone unturned. The people deserve better.**",[("{{Let me be perfectly clear}}: we will not give up.","Deixe-me ser perfeitamente claro: não desistiremos."),("{{We will leave no stone unturned}} until we find answers.","Não deixaremos pedra sobre pedra até achar respostas."),("{{The people deserve better}} than this.","O povo merece algo melhor que isso."),("{{Make no mistake}}.","Não se enganem.")],"“Leave no stone unturned” =",["esgotar todas as possibilidades","não mexer em pedras","construir"],0,"Tudo tentar."),
84153:("Percebendo manipulação","**Notice the pressure to pay at once. That argument plays on guilt. Let me take a step back.**",[("{{Notice}} the pressure to pay at once.","Perceba a pressão para pagar já."),("{{That argument plays on guilt}}.","Esse argumento joga com a culpa."),("{{Let me take a step back}} and think.","Deixe-me dar um passo atrás e pensar."),("{{I won't be rushed}}.","Não vou me apressar.")],"“Play on” (culpa) =",["explorar","tocar em","jogar"],0,"Explorar."),
84154:("Revisão de retórica","**This review is long overdue. Where is your evidence? I would like to offer a rebuttal.**",[("{{This review is long overdue}} for our team.","Esta revisão há muito é devida à nossa equipe."),("{{Where is your evidence}} for this plan?","Onde está a evidência do seu plano?"),("{{I would like to offer a rebuttal}} with two reasons.","Gostaria de oferecer uma réplica com duas razões."),("{{Let me summarize}}.","Deixe-me resumir.")],"“Rebuttal” =",["réplica/refutação","rebatismo","rebote"],0,"Refutação."),
950064:("water down / dial back","**Water down** = enfraquecer; **dumb down** = simplificar demais; **dial back** = reduzir; **soft-pedal**; **anodyne** = inofensivo.",[("Don't {{water down}} the news.","Não enfraqueça a notícia."),("They {{dumbed down}} the text.","Eles simplificaram demais o texto."),("{{Dial back}} the risk.","Reduza o risco."),("An {{anodyne}} report.","Um relatório insosso.")],"“Anodyne” =",["insosso/inofensivo","anônimo","anormal"],0,"Inofensivo."),
84155:("Planejamento estratégico","**Our vision is to… Here is our roadmap for this quarter. The next milestone is…**",[("{{Our vision is to}} serve every customer.","Nossa visão é atender todos os clientes."),("{{Here is our roadmap}} for this quarter.","Eis nosso roteiro para este trimestre."),("{{The next milestone is}} one thousand users.","O próximo marco são mil usuários."),("{{We'll track progress}} monthly.","Acompanharemos o progresso mensalmente.")],"“Milestone” =",["marco","pedra de moinho","milha"],0,"Marco."),
950065:("a bone of contention","**A bone of contention** = pomo da discórdia; **a perfect storm**; **a pipe dream** = sonho impossível.",[("It's {{a bone of contention}}.","É um pomo da discórdia."),("A {{perfect storm}} of events.","Uma tempestade perfeita de eventos."),("It's {{a pipe dream}}.","É um sonho impossível."),("It's {{a sore point}}.","É um ponto sensível.")],"“Pipe dream” =",["sonho irrealizável","sonho de cachimbo","sono"],0,"Irreal."),
84156:("Estilos de liderança","**I prefer to lead by example. I try not to micromanage. I trust my people to do their best.**",[("{{I prefer to lead by example}}.","Prefiro liderar pelo exemplo."),("{{I try not to micromanage}} small details.","Tento não microgerenciar detalhes."),("{{I trust my people}} to do their best.","Confio que minha equipe dê o seu melhor."),("{{I stay calm}} under pressure.","Mantenho a calma sob pressão.")],"“Micromanage” =",["controlar cada detalhe","gerenciar pouco","gerenciar em micro"],0,"Controlar."),
84157:("Motivando uma equipe","**I have every confidence in your skills. Let us rally around this project. Your effort has not gone unnoticed.**",[("{{I have every confidence in}} your skills.","Tenho total confiança em suas habilidades."),("{{Let us rally around}} this project.","Vamos nos unir em torno deste projeto."),("{{Your effort has not gone unnoticed}}.","Seu esforço não passou despercebido."),("{{Keep up the great work}}.","Continue o ótimo trabalho.")],"“Rally around” =",["unir-se em torno","correr","girar"],0,"Unir."),
84158:("Delegando e empoderando","**I would like to entrust you with… I want you to take ownership of… Come to me if you need support.**",[("{{I would like to entrust you with}} the new client.","Gostaria de confiar a você o novo cliente."),("{{I want you to take ownership of}} this task.","Quero que você assuma esta tarefa como sua."),("{{Come to me if you need support}}.","Venha a mim se precisar de apoio."),("{{I'll back you up}}.","Estarei ao seu lado.")],"“Take ownership” =",["assumir a responsabilidade","pegar posse","comprar"],0,"Responsabilidade."),
84159:("Gerenciando mudanças","**It is crucial that we listen to concerns. We will roll out the new system next month. I understand your concerns.**",[("{{It is crucial that}} we {{listen}} to concerns.","É crucial que ouçamos as preocupações."),("{{We will roll out}} the new system next month.","Implantaremos o novo sistema no mês que vem."),("{{I understand your concerns}} about the timeline.","Entendo suas preocupações com o prazo."),("{{Change is hard}}, but necessary.","Mudar é difícil, mas necessário.")],"“Roll out” (sistema) =",["implantar","enrolar","rolar"],0,"Implantar."),
950066:("esclarecimento","**If I understand you correctly… Could you elaborate on…? What exactly do you mean? I'm not sure I follow.**",[("{{If I understand you correctly}}, it's a risk.","Se entendi bem, é um risco."),("{{Could you elaborate on}} that?","Poderia detalhar isso?"),("{{What exactly do you mean}}?","O que exatamente você quer dizer?"),("{{I'm not sure I follow}}.","Não tenho certeza de que acompanho.")],"“I'm not sure I follow” =",["não entendi bem","não vou seguir","não tenho certeza de seguir uma pessoa"],0,"Não acompanho."),
84160:("Finanças corporativas","**Our margins have narrowed. Liquidity is our main concern. According to our forecast…**",[("{{Our margins have narrowed}} this year.","Nossas margens diminuíram este ano."),("{{Liquidity is our main concern}} at the moment.","A liquidez é nossa principal preocupação no momento."),("{{According to our forecast}}, costs will fall.","Segundo nossa projeção, os custos cairão."),("{{Cash flow}} is positive.","O fluxo de caixa é positivo.")],"“Liquidity” =",["liquidez","líquido só","líder"],0,"Liquidez."),
84161:("Fusões e aquisições","**They have made a bid for… This is a hostile takeover… The merger is subject to approval.**",[("{{They have made a bid for}} a rival firm.","Fizeram uma oferta por uma empresa rival."),("{{This is a hostile takeover}}, and the board objected.","Isso é uma aquisição hostil, e o conselho se opôs."),("{{The merger is subject to}} approval by shareholders.","A fusão está sujeita à aprovação dos acionistas."),("{{Shares jumped}}.","As ações dispararam.")],"“Takeover” =",["aquisição/tomada de controle","decolagem","tomar o controle remoto"],0,"Aquisição."),
950067:("act up / bump into","**Act up** = dar problema; **beef up** = reforçar; **bump into** = esbarrar; **burst into** = irromper.",[("My knee {{acts up}}.","Meu joelho dá problema."),("I {{bumped into}} him.","Esbarrei nele."),("We must {{beef up}} security.","Precisamos reforçar a segurança."),("She {{burst into}} tears.","Ela caiu em lágrimas.")],"“Beef up” =",["reforçar","engordar bife","alimentar"],0,"Reforçar."),
84162:("Táticas de negociação","**Let us find some common ground. We are prepared to make a concession. Let us meet halfway.**",[("{{Let us find some common ground}} on delivery.","Vamos achar um ponto em comum sobre a entrega."),("{{We are prepared to make a concession}} on delivery time.","Estamos dispostos a ceder no prazo de entrega."),("{{Let us meet halfway}} on the schedule.","Vamos nos encontrar no meio do caminho no cronograma."),("{{That works for us}}.","Isso funciona para nós.")],"“Concession” =",["concessão","conclusão","conexão"],0,"Ceder."),
84163:("Fechando um negócio","**Let us seal the deal with a handshake. Please sign on the dotted line. I look forward to working with you.**",[("{{Let us seal the deal}} with a handshake.","Vamos selar o acordo com um aperto de mão."),("{{Please sign on the dotted line}} below.","Assine na linha pontilhada abaixo."),("{{I look forward to working with you}} this year.","Aguardo trabalhar com você neste ano."),("{{We have a deal}}.","Temos um acordo.")],"“Sign on the dotted line” =",["assinar o contrato","pontilhar","desenhar linha"],0,"Assinar."),
950068:("elipse","Na fala informal, omitimos o óbvio: **Want some? Sounds good. Been there. Sure, why not.**",[("{{Want some}} coffee?","Quer café?"),("{{Sounds good}}.","Parece bom."),("{{Been there}}.","Já passei por isso."),("{{Sure, why not}}.","Claro, por que não.")],"“Want some?” omite…",["Do you","You","Are you"],0,"Do you."),
84164:("Apresentações de vendas","**This is a turnkey solution. Customers rave about its design. The bottom line is that you save time.**",[("{{This is a turnkey solution}} for small firms.","Esta é uma solução pronta para uso para pequenas empresas."),("{{Customers rave about}} its design.","Os clientes elogiam muito seu design."),("{{The bottom line is that}} you save time.","O ponto principal é que você economiza tempo."),("{{It pays for itself}}.","Se paga sozinho.")],"“Turnkey” =",["pronto para usar","chave giratória","fechadura"],0,"Pronto."),
84165:("Startups e investimento","**We just closed our seed round. We have twelve months of runway. We plan to scale across Europe.**",[("{{We just closed our seed round}} in March.","Acabamos de fechar a rodada semente em março."),("{{We have twelve months of runway}} if sales hold.","Temos doze meses de fôlego se as vendas se mantiverem."),("{{We plan to scale}} across Europe.","Planejamos crescer pela Europa."),("{{Investors are on board}}.","Os investidores estão a bordo.")],"“Runway” (startup) =",["fôlego financeiro","pista de pouso","caminho"],0,"Tempo de caixa."),
84166:("Relacionamento com clientes","**We go the extra mile. I am sorry for the inconvenience, and I will fix it. We value your feedback.**",[("{{We go the extra mile}} to help you.","Fazemos mais do que o esperado para ajudar você."),("{{I am sorry for the inconvenience}} and I will fix it.","Lamento o transtorno e vou resolver."),("{{We value your feedback}} on our service.","Valorizamos seu retorno sobre nosso serviço."),("{{Rest assured}}.","Fique tranquilo.")],"“Rest assured” =",["fique tranquilo","descanse seguro","aposente-se"],0,"Tranquilo."),
950069:("back to square one","**Back to square one** = recomeçar; **a hot potato** = assunto delicado; **in the same boat** = na mesma situação.",[("We're {{back to square one}}.","Voltamos à estaca zero."),("It's {{a hot potato}}.","É uma batata quente."),("We're {{in the same boat}}.","Estamos no mesmo barco."),("It's {{a Catch-22}}.","É um dilema sem saída.")],"“Hot potato” =",["assunto delicado","batata quente literal só","comida cara"],0,"Assunto espinhoso."),
84167:("Dilemas éticos nos negócios","**It is a gray area, but I disagree. I cannot in good conscience sign this report. Integrity must trump profit.**",[("{{It is a gray area}}, but I disagree.","É uma zona cinzenta, mas discordo."),("{{I cannot in good conscience}} sign this report.","Não posso, em sã consciência, assinar este relatório."),("{{Integrity must trump profit}}, in my view.","A integridade deve vencer o lucro, na minha visão."),("{{That crosses the line}}.","Isso passa dos limites.")],"“Gray area” =",["zona cinzenta","área cinza só","sombra"],0,"Ambíguo."),
950070:("cut the mustard","**Cut the mustard / make the cut** = ter o nível exigido; **hold a candle to** = comparar-se; **a feather in one's cap**.",[("She can't {{cut the mustard}}.","Ela não está à altura."),("Nobody {{holds a candle to}} her.","Ninguém se compara a ela."),("He didn't {{make the cut}}.","Ele não foi selecionado."),("It's {{a feather in your cap}}.","É uma conquista sua.")],"“Hold a candle to” =",["comparar-se a","segurar vela","iluminar"],0,"Comparar."),
84168:("Cultura corporativa","**Morale is at an all-time low. We want to foster a culture of respect. It starts at the top.**",[("{{Morale is at an all-time low}} this year.","O moral está na pior de todos os tempos este ano."),("{{We want to foster a culture of respect}}.","Queremos cultivar uma cultura de respeito."),("{{It starts at the top}} every time.","Começa sempre no topo."),("{{Trust is earned}}.","A confiança é conquistada.")],"“Foster” =",["cultivar/promover","fosco","ficar"],0,"Promover."),
84169:("Trabalho remoto e híbrido","**I work remotely on Mondays. It is hard to set boundaries. Let us sync up tomorrow morning.**",[("{{I work remotely}} on Mondays.","Trabalho remotamente às segundas."),("{{It is hard to set boundaries}} with my team.","É difícil estabelecer limites com a equipe."),("{{Let us sync up}} tomorrow morning.","Vamos alinhar amanhã de manhã."),("{{We're on a hybrid schedule}}.","Estamos em regime híbrido.")],"“Sync up” =",["alinhar","sincronizar relógio só","conectar"],0,"Alinhar."),
84170:("Empreendedorismo","**I started the business from scratch. We found a niche in online sales. It is part and parcel of being a founder.**",[("{{I started the business from scratch}} five years ago.","Comecei o negócio do zero há cinco anos."),("{{We found a niche}} in online sales.","Achamos um nicho nas vendas on-line."),("{{It is part and parcel of}} being a founder.","Faz parte de ser fundador."),("{{We bootstrapped}} the company.","Financiamos a empresa com recursos próprios.")],"“From scratch” =",["do zero","da arranhadura","do arranhão"],0,"Do zero."),
84171:("Risco e contingência","**We need a contingency plan. We can mitigate this risk by adding a buffer. If all else fails, we call the client.**",[("{{We need a contingency plan}} for supply problems.","Precisamos de um plano de contingência para problemas de suprimento."),("{{We can mitigate this risk}} by adding a buffer.","Podemos mitigar esse risco acrescentando uma margem."),("{{If all else fails}}, we call the client.","Se tudo falhar, ligamos para o cliente."),("{{Worst-case scenario}}, we delay.","No pior cenário, adiamos.")],"“Mitigate” =",["mitigar","migrar","mover"],0,"Mitigar."),
950071:("degustação","**Vintage** = safra; **tannin** = sensação seca; **palate** = paladar; **terroir**; *swirl* = girar; *pair with* = combinar com.",[("{{Swirl}} the red.","Gire o vinho tinto."),("It {{pairs with}} fish.","Combina com peixe."),("A fine {{vintage}}.","Uma ótima safra."),("A refined {{palate}}.","Um paladar refinado.")],"“Palate” =",["paladar","palanque","palavra"],0,"Paladar."),
84172:("Negócios entre culturas","**Please bear in mind that titles matter here. It is considered rude to arrive late. With your consent…**",[("{{Please bear in mind}} that titles matter here.","Tenha em mente que títulos importam aqui."),("{{It is considered rude to}} arrive late.","É considerado rude chegar atrasado."),("{{With your consent}}, I will take notes.","Com seu consentimento, vou anotar."),("{{When in Rome}}…","Onde estiver…")],"“Bear in mind” =",["ter em mente","carregar mente","urso"],0,"Lembrar."),
950072:("cough up / dip into","**Cough up** = pagar a contragosto; **dip into** = usar parte de uma reserva; **dish out** = distribuir; **duck out of**.",[("He {{coughed up}} the cash.","Ele desembolsou o dinheiro a contragosto."),("We had to {{dip into}} savings.","Tivemos de usar parte da poupança."),("She {{dishes out}} advice.","Ela distribui conselhos."),("He {{ducked out of}} it.","Ele escapou disso.")],"“Dip into” (poupança) =",["usar parte da reserva","mergulhar","molhar"],0,"Usar parte."),
84173:("Linguagem legal","**This is a breach of contract. All staff must comply with the law. Pursuant to the agreement, notice is required.**",[("{{This is a breach of contract}} in my view.","Isto é uma quebra de contrato, na minha visão."),("{{All staff must comply with}} the law.","Todos os funcionários devem cumprir a lei."),("{{Pursuant to}} the agreement, notice is required.","Nos termos do acordo, é necessário aviso."),("{{The party is liable}}.","A parte é responsável.")],"“Pursuant to” =",["nos termos de","perseguindo","perto de"],0,"Conforme."),
84174:("Melhoria de processos","**We need to streamline the process. The bottleneck is in shipping. We measure ourselves against the benchmark.**",[("{{We need to streamline}} the process for our clients.","Precisamos simplificar o processo para nossos clientes."),("{{The bottleneck is in}} shipping.","O gargalo está no envio."),("{{We measure ourselves against the benchmark}} in our industry.","Nos medimos pelo padrão do nosso setor."),("{{Let's cut waste}}.","Vamos cortar desperdício.")],"“Bottleneck” =",["gargalo","pescoço de garrafa só","fila"],0,"Gargalo."),
84175:("Falar em público nos negócios","**I will keep this brief. The key takeaway is… I will now open the floor to comments.**",[("{{I will keep this brief}} and clear.","Serei breve e claro."),("{{The key takeaway is that}} trust matters most.","A principal lição é que a confiança importa mais."),("{{I will now open the floor}} to comments.","Agora abro a palavra para comentários."),("{{Let me close with}} one idea.","Deixe-me encerrar com uma ideia.")],"“Takeaway” =",["lição principal","comida para viagem só","retirar"],0,"Lição."),
84176:("Resolução de conflitos","**I would like to raise a grievance. Let us try to find common ground. I see where you are coming from.**",[("{{I would like to raise a grievance}} about unfair treatment.","Gostaria de registrar uma queixa formal por tratamento injusto."),("{{Let us try to find common ground}} on this issue.","Vamos tentar achar um ponto em comum."),("{{I see where you are coming from}}, but I see it differently.","Entendo seu ponto de vista, mas vejo de outro modo."),("{{Let's keep it professional}}.","Vamos manter o profissionalismo.")],"“Grievance” =",["queixa formal","grave","grão"],0,"Queixa."),
950073:("brush aside","**Brush aside / wave away** = ignorar; **laugh off** = levar na brincadeira; **write off** = dar como perdido.",[("She {{brushed aside}} the warning.","Ela ignorou o aviso."),("They {{laughed off}} the idea.","Eles levaram a ideia na brincadeira."),("The bank {{wrote off}} the loan.","O banco deu o empréstimo como perdido."),("He {{waved away}} her concerns.","Ele dispensou as preocupações dela.")],"“Write off” (dívida) =",["dar como perdido","escrever fora","cancelar viagem só"],0,"Baixa."),
84177:("Mentoria e carreira","**She took me under her wing. I am aiming to climb the corporate ladder. I would value your guidance.**",[("{{She took me under her wing}} when I joined.","Ela me acolheu quando entrei."),("{{I am aiming to climb the corporate ladder}} in this firm.","Pretendo subir na carreira nesta empresa."),("{{I would value your guidance}} on my career.","Valorizaria sua orientação na minha carreira."),("{{Could you mentor me}}?","Poderia me orientar?")],"“Take under one's wing” =",["acolher/orientar","arrancar asa","voar"],0,"Proteger."),
950074:("ease off / egg on","**Ease off** = reduzir o ritmo; **egg on** = incitar; **fade out** = sumir aos poucos; **fess up** = confessar.",[("The rain {{eased off}}.","A chuva diminuiu."),("Don't {{egg}} him {{on}}.","Não o incite."),("The music {{faded out}}.","A música foi sumindo."),("{{Fess up}}!","Confesse!")],"“Egg on” =",["incitar","pôr ovo","fritar"],0,"Incitar."),
84178:("Equilíbrio trabalho-vida","**I am stretched too thin. I need to find a better balance before I burn out. Family is my top priority.**",[("{{I am stretched too thin}} this month.","Estou sobrecarregado este mês."),("{{I need to find a better balance}} before I burn out.","Preciso achar um equilíbrio antes de esgotar."),("{{Family is my top priority}} this year.","A família é minha prioridade este ano."),("{{I'm setting boundaries}}.","Estou estabelecendo limites.")],"“Burn out” =",["esgotar-se","queimar fora","apagar"],0,"Esgotamento."),
84179:("Tendências econômicas","**The economy is showing signs of recovery. Consumer confidence is starting to wane. We may be heading into a recession.**",[("{{The economy is showing signs of recovery}} at last.","A economia mostra sinais de recuperação enfim."),("{{Consumer confidence is starting to wane}}.","A confiança do consumidor começa a diminuir."),("{{We may be heading into a recession}}, experts warn.","Podemos estar rumo a uma recessão, alertam especialistas."),("{{Inflation is easing}}.","A inflação está cedendo.")],"“Wane” =",["diminuir","ganhar","esperar"],0,"Diminuir."),
84180:("Sustentabilidade","**We aim to cut our carbon footprint. Every product is fully traceable. We are committed to net zero by 2050.**",[("{{We aim to cut our carbon footprint}} by twenty percent.","Pretendemos reduzir nossa pegada de carbono em vinte por cento."),("{{Every product is fully traceable}} to the farm.","Todo produto é totalmente rastreável até a fazenda."),("{{We are committed to net zero}} by 2050.","Estamos comprometidos com emissões líquidas zero até 2050."),("{{We source responsibly}}.","Compramos de forma responsável.")],"“Net zero” =",["emissões líquidas zero","rede zero","zero puro"],0,"Neutro."),
950075:("cast a shadow","**Cast a shadow** = ter efeito negativo; **cast aspersions** = difamar; **cast a spell** = encantar; **cast an eye** = olhar.",[("It {{cast a shadow}} on everyone.","Isso lançou uma sombra sobre todos."),("Don't {{cast aspersions}}.","Não lance calúnias."),("The song {{cast a spell}}.","A canção lançou um feitiço."),("She {{cast an eye}} over it.","Ela deu uma olhada.")],"“Cast aspersions” =",["difamar","lançar âncora","lançar luz"],0,"Difamar."),
84181:("Tecnologia nos negócios","**This technology could disrupt the banking sector. Analytics show… We need a scalable solution.**",[("{{This technology could disrupt}} the banking sector.","Esta tecnologia poderia revolucionar o setor bancário."),("{{Analytics show that}} sales peak on Fridays.","Os dados mostram que as vendas atingem o pico às sextas."),("{{We need a scalable solution}} that can handle demand.","Precisamos de uma solução escalável que aguente a demanda."),("{{It streamlines operations}}.","Simplifica as operações.")],"“Scalable” =",["escalável","escamoso","escalado"],0,"Escalável."),
84182:("Revisão: comunicação empresarial","**Let us revisit our main points. Our top priority is customer trust. We need to align on the budget.**",[("{{Let us revisit}} our main points from this unit.","Vamos rever nossos pontos principais desta unidade."),("{{Our top priority is}} customer trust.","Nossa principal prioridade é a confiança do cliente."),("{{We need to align on}} the budget.","Precisamos nos alinhar sobre o orçamento."),("{{Let's circle back}} on Friday.","Voltamos a isso na sexta.")],"“Align on” =",["alinhar-se sobre","alinhar na","colocar em linha só"],0,"Alinhar."),
84183:("Viés da mídia","**The article has a clear slant. The story is framed as a crisis. That claim lacks a reliable source.**",[("{{The article has a clear slant}} against the strikers.","O artigo tem um viés claro contra os grevistas."),("{{The story is framed as}} a crisis.","A história é apresentada como uma crise."),("{{That claim lacks a reliable source}} and should be checked.","Essa afirmação carece de fonte confiável e deve ser checada."),("{{Check the byline}}.","Confira a autoria.")],"“Slant” (mídia) =",["viés","inclinar só","rampa"],0,"Viés."),
950076:("the grass is greener","**The grass is greener** = achar o dos outros melhor; **the early bird**; **add insult to injury**; **a loose cannon**.",[("{{The grass looks greener}} on the other side.","A grama parece mais verde do outro lado."),("{{The early bird}} catches the worm.","Deus ajuda quem cedo madruga."),("{{To add insult to injury}}, it rained.","Para piorar, choveu."),("He's {{a loose cannon}}.","Ele é imprevisível.")],"“Add insult to injury” =",["piorar a situação","insultar","ferir"],0,"Piorar."),
84184:("Desinformação e bolhas","**The rumor went viral. Algorithms amplify outrage. It has been debunked by experts.**",[("{{The rumor went viral}} within hours.","O boato viralizou em horas."),("{{Algorithms amplify outrage}} very quickly.","Algoritmos amplificam indignação muito rápido."),("{{It has been debunked}} by experts.","Foi desmentido por especialistas."),("{{Echo chambers}} reinforce beliefs.","Bolhas reforçam crenças.")],"“Echo chamber” =",["bolha de opinião","câmara de eco só","eco"],0,"Bolha."),
950077:("gírias escocesas","**Dinnae / cannae** = don't / can't; **blether** = conversar; **haver** = falar bobagem; **dreich** = cinzento e úmido.",[("{{Dinnae}} worry.","Não se preocupe."),("They {{blether}} all day.","Eles conversam o dia todo."),("A {{dreich}} day.","Um dia cinzento e úmido."),("He's {{havering}}.","Ele está falando bobagem.")],"“Dreich” =",["cinzento e úmido","ensolarado","frio seco"],0,"Tempo feio."),
84185:("Privacidade e vigilância","**Apps track our location without asking. I value my privacy, so I read the terms. I have nothing to hide, but privacy matters.**",[("{{Apps track our location}} without asking.","Aplicativos rastreiam nossa localização sem perguntar."),("{{I value my privacy}}, so I read the terms.","Valorizo minha privacidade, então leio os termos."),("{{I have nothing to hide}}, but privacy matters.","Não tenho nada a esconder, mas a privacidade importa."),("{{Surveillance is spreading}}.","A vigilância está se espalhando.")],"“Surveillance” =",["vigilância","sobrevivência","supervisão"],0,"Vigilância."),
84186:("Liberdade de expressão","**Free speech is a fundamental right. Where do we draw the line? Censorship can stifle debate.**",[("{{Free speech is a fundamental right}} in my view.","A liberdade de expressão é um direito fundamental, na minha visão."),("{{Where do we draw the line}} at threats?","Onde traçamos o limite em ameaças?"),("{{Censorship can stifle debate}} in schools.","A censura pode sufocar o debate nas escolas."),("{{Hate speech}} is different.","Discurso de ódio é diferente.")],"“Stifle” =",["sufocar","estilizar","estudar"],0,"Sufocar."),
84187:("Democracia e polarização","**Society is increasingly polarized. Trust in institutions is declining. We need to listen across the divide.**",[("{{Society is increasingly polarized}} these days.","A sociedade está cada vez mais polarizada hoje."),("{{Trust in institutions is declining}} according to polls.","A confiança nas instituições está em queda, segundo pesquisas."),("{{We need to listen across the divide}} more often.","Precisamos ouvir do outro lado com mais frequência."),("{{Turnout is falling}}.","A participação eleitoral está caindo.")],"“Polarized” =",["polarizado","polido","polar"],0,"Dividido."),
84188:("Movimentos sociais","**The movement is gaining momentum. Activists mobilize supporters door to door. They are calling for reform.**",[("{{The movement is gaining momentum}} every day.","O movimento ganha força a cada dia."),("{{Activists mobilize}} supporters door to door.","Ativistas mobilizam apoiadores de porta em porta."),("{{They are calling for reform}} this year.","Eles pedem reforma este ano."),("{{Grassroots groups}} lead the way.","Grupos de base lideram.")],"“Gain momentum” =",["ganhar força","ganhar momento só","ganhar peso"],0,"Ganhar impulso."),
}
